-- Serie 5: consignas textuales del archivo recibido y resoluciones didácticas.
-- Se agregan a la Unidad 5 sin borrar el problema integrador existente.
begin;
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',5,'serie-5',$cbc$Ejercicio 5.1$cbc$,$cbc$<div class="u5Verbatim" data-source="serie5_ejercicios_resueltos.md"><p><strong>5.1] Determinar el estado de oxidación de cada elemento en las especies siguientes:</strong></p><p><strong>a)</strong> <span class="u5Math" data-latex="%5Ctext%7BNaH%7D%2C%20%5Ctext%7BNH%7D_3%2C%20%5Ctext%7BH%7D_2%5Ctext%7BSO%7D_4%2C%20%5Ctext%7BHCl%7D%2C%20%5Ctext%7BCH%7D_4" data-display="false"></span>;</p><p><strong>b)</strong> <span class="u5Math" data-latex="%5Ctext%7BSO%7D_2%2C%20%5Ctext%7BNO%7D%2C%20%5Ctext%7BSO%7D_3%2C%20%5Ctext%7BSiO%7D_2%2C%20%5Ctext%7BNO%7D_2" data-display="false"></span>;</p><p><strong>c)</strong> <span class="u5Math" data-latex="%5Ctext%7BCuF%7D_2%2C%20%5Ctext%7BKH%7D%2C%20%5Ctext%7BFeCl%7D_3%2C%20%5Ctext%7BCoBr%7D_2" data-display="false"></span>;</p><p><strong>d)</strong> <span class="u5Math" data-latex="%5Ctext%7BMg%7D%5E%7B2%2B%7D%2C%20%5Ctext%7BSO%7D_4%5E%7B2-%7D%2C%20%5Ctext%7BFe%7D%5E%7B3%2B%7D%2C%20%5Ctext%7BCl%7D%5E-" data-display="false"></span>;</p><p><strong>e)</strong> <span class="u5Math" data-latex="%5Ctext%7BNH%7D_4%5E%2B%2C%20%5Ctext%7BNO%7D_3%5E-%2C%20%5Ctext%7BPO%7D_4%5E%7B3-%7D" data-display="false"></span> y <span class="u5Math" data-latex="%5Ctext%7BHS%7D%5E-" data-display="false"></span>.</p></div>$cbc$,'Serie 5 · Química CBC · Cátedra Di Risio', 20, false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html, source_label=excluded.source_label, sort_order=excluded.sort_order, updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u5Lead">Primero asigná los valores conocidos; después despejá el elemento que falta. En una molécula la suma es cero; en un ion es su carga.</p><div class="u5Step"><span>Regla</span><div><div class="u5Equation"><div class="u5Math" data-latex="%5Csum_i%20n_i%5C%2CEO_i%3Dq" data-display="true"></div></div><p>En cada elemento, multiplicá el estado de oxidación por su subíndice. Para una especie neutra, q = 0.</p></div></div><details class="u5Subsolution"><summary>Ítem a) · Hidrógeno en compuestos</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Especie</th><th>Cuenta del elemento desconocido</th><th>Estados de oxidación</th></tr></thead><tbody><tr><td><strong>NaH</strong></td><td><span class="u5Math" data-latex="%28%2B1%29%2Bx%3D0%5CRightarrow%20x%3D-1" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BNa%7D%28%2B1%29%2C%5C%20H%28-1%29" data-display="false"></span></td></tr><tr><td><strong>NH3</strong></td><td><span class="u5Math" data-latex="x%2B3%28%2B1%29%3D0%5CRightarrow%20x%3D-3" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BN%7D%28-3%29%2C%5C%20H%28%2B1%29" data-display="false"></span></td></tr><tr><td><strong>H2SO4</strong></td><td><span class="u5Math" data-latex="2%28%2B1%29%2Bx%2B4%28-2%29%3D0%5CRightarrow%20x%3D%2B6" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BH%7D%28%2B1%29%2C%5C%20S%28%2B6%29%2C%5C%20O%28-2%29" data-display="false"></span></td></tr><tr><td><strong>HCl</strong></td><td><span class="u5Math" data-latex="%28%2B1%29%2Bx%3D0%5CRightarrow%20x%3D-1" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BH%7D%28%2B1%29%2C%5C%20Cl%28-1%29" data-display="false"></span></td></tr><tr><td><strong>CH4</strong></td><td><span class="u5Math" data-latex="x%2B4%28%2B1%29%3D0%5CRightarrow%20x%3D-4" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BC%7D%28-4%29%2C%5C%20H%28%2B1%29" data-display="false"></span></td></tr></tbody></table></div><aside class="u5Tip"><strong>Clave:</strong> En NaH el H vale −1 por ser hidruro metálico; en NH₃, H₂SO₄, HCl y CH₄ vale +1.</aside></div></details><details class="u5Subsolution"><summary>Ítem b) · Óxidos</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Especie</th><th>Cuenta del elemento desconocido</th><th>Estados de oxidación</th></tr></thead><tbody><tr><td><strong>SO2</strong></td><td><span class="u5Math" data-latex="x%2B2%28-2%29%3D0%5CRightarrow%20x%3D%2B4" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BS%7D%28%2B4%29%2C%5C%20O%28-2%29" data-display="false"></span></td></tr><tr><td><strong>NO</strong></td><td><span class="u5Math" data-latex="x%2B%28-2%29%3D0%5CRightarrow%20x%3D%2B2" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BN%7D%28%2B2%29%2C%5C%20O%28-2%29" data-display="false"></span></td></tr><tr><td><strong>SO3</strong></td><td><span class="u5Math" data-latex="x%2B3%28-2%29%3D0%5CRightarrow%20x%3D%2B6" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BS%7D%28%2B6%29%2C%5C%20O%28-2%29" data-display="false"></span></td></tr><tr><td><strong>SiO2</strong></td><td><span class="u5Math" data-latex="x%2B2%28-2%29%3D0%5CRightarrow%20x%3D%2B4" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BSi%7D%28%2B4%29%2C%5C%20O%28-2%29" data-display="false"></span></td></tr><tr><td><strong>NO2</strong></td><td><span class="u5Math" data-latex="x%2B2%28-2%29%3D0%5CRightarrow%20x%3D%2B4" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BN%7D%28%2B4%29%2C%5C%20O%28-2%29" data-display="false"></span></td></tr></tbody></table></div></div></details><details class="u5Subsolution"><summary>Ítem c) · Sales e hidruros</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Especie</th><th>Cuenta del elemento desconocido</th><th>Estados de oxidación</th></tr></thead><tbody><tr><td><strong>CuF2</strong></td><td><span class="u5Math" data-latex="x%2B2%28-1%29%3D0%5CRightarrow%20x%3D%2B2" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BCu%7D%28%2B2%29%2C%5C%20F%28-1%29" data-display="false"></span></td></tr><tr><td><strong>KH</strong></td><td><span class="u5Math" data-latex="%28%2B1%29%2Bx%3D0%5CRightarrow%20x%3D-1" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BK%7D%28%2B1%29%2C%5C%20H%28-1%29" data-display="false"></span></td></tr><tr><td><strong>FeCl3</strong></td><td><span class="u5Math" data-latex="x%2B3%28-1%29%3D0%5CRightarrow%20x%3D%2B3" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BFe%7D%28%2B3%29%2C%5C%20Cl%28-1%29" data-display="false"></span></td></tr><tr><td><strong>CoBr2</strong></td><td><span class="u5Math" data-latex="x%2B2%28-1%29%3D0%5CRightarrow%20x%3D%2B2" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BCo%7D%28%2B2%29%2C%5C%20Br%28-1%29" data-display="false"></span></td></tr></tbody></table></div></div></details><details class="u5Subsolution"><summary>Ítem d) · Iones monoatómicos y sulfato</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Especie</th><th>Cuenta del elemento desconocido</th><th>Estados de oxidación</th></tr></thead><tbody><tr><td><strong>Mg²⁺</strong></td><td><span class="u5Math" data-latex="x%3D%2B2" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BMg%7D%28%2B2%29" data-display="false"></span></td></tr><tr><td><strong>SO₄²⁻</strong></td><td><span class="u5Math" data-latex="x%2B4%28-2%29%3D-2%5CRightarrow%20x%3D%2B6" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BS%7D%28%2B6%29%2C%5C%20O%28-2%29" data-display="false"></span></td></tr><tr><td><strong>Fe³⁺</strong></td><td><span class="u5Math" data-latex="x%3D%2B3" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BFe%7D%28%2B3%29" data-display="false"></span></td></tr><tr><td><strong>Cl⁻</strong></td><td><span class="u5Math" data-latex="x%3D-1" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BCl%7D%28-1%29" data-display="false"></span></td></tr></tbody></table></div><aside class="u5Tip"><strong>Clave:</strong> Para un ion monoatómico, el estado de oxidación coincide directamente con la carga. En SO₄²⁻, la suma de todos los átomos da −2.</aside></div></details><details class="u5Subsolution"><summary>Ítem e) · Iones poliatómicos</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Especie</th><th>Cuenta del elemento desconocido</th><th>Estados de oxidación</th></tr></thead><tbody><tr><td><strong>NH₄⁺</strong></td><td><span class="u5Math" data-latex="x%2B4%28%2B1%29%3D%2B1%5CRightarrow%20x%3D-3" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BN%7D%28-3%29%2C%5C%20H%28%2B1%29" data-display="false"></span></td></tr><tr><td><strong>NO₃⁻</strong></td><td><span class="u5Math" data-latex="x%2B3%28-2%29%3D-1%5CRightarrow%20x%3D%2B5" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BN%7D%28%2B5%29%2C%5C%20O%28-2%29" data-display="false"></span></td></tr><tr><td><strong>PO₄³⁻</strong></td><td><span class="u5Math" data-latex="x%2B4%28-2%29%3D-3%5CRightarrow%20x%3D%2B5" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BP%7D%28%2B5%29%2C%5C%20O%28-2%29" data-display="false"></span></td></tr><tr><td><strong>HS⁻</strong></td><td><span class="u5Math" data-latex="%28%2B1%29%2Bx%3D-1%5CRightarrow%20x%3D-2" data-display="false"></span></td><td><span class="u5Math" data-latex="%5Cmathrm%7BH%7D%28%2B1%29%2C%5C%20S%28-2%29" data-display="false"></span></td></tr></tbody></table></div></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',5,'serie-5',$cbc$Ejercicio 5.2$cbc$,$cbc$<div class="u5Verbatim" data-source="serie5_ejercicios_resueltos.md"><p><strong>5.2] La mayoría de los elementos de la Tabla Periódica forman compuestos binarios con el oxígeno. En los compuestos llamados óxidos el oxígeno tiene estado de oxidación -2.</strong></p><p><strong>a)</strong> Aplicando las reglas del estado de oxidación, escribir la fórmula y nombrar a los óxidos de los elementos siguientes: 1) azufre, con estados de oxidación +4 y +6; 2) nitrógeno, con estado de oxidación +3 y +5; 3) cloro, con estados de oxidación +1 y +7; 4) calcio; 5) sodio; 6) hierro, con estados de oxidación +2 y +3.</p><p><strong>b)</strong> Hacer una lista de los óxidos predominantemente iónicos y otra de los óxidos predominantemente covalentes para los compuestos del ítem anterior.</p><p><strong>c)</strong> Representar una estructura de Lewis para cada uno de ellos.</p><p><em>Nota: en el óxido de nitrógeno (V), cada átomo de nitrógeno se encuentra unido a tres átomos de oxígeno; En el óxido de cloro (VII), cada átomo de cloro se encuentra unido a cuatro átomos de oxígeno.</em></p></div>$cbc$,'Serie 5 · Química CBC · Cátedra Di Risio', 30, false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html, source_label=excluded.source_label, sort_order=excluded.sort_order, updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u5Lead">Usá O = −2, elegí los subíndices mínimos que hagan cero la suma y recién después poné el nombre.</p><details class="u5Subsolution" open><summary>a) Fórmulas, comprobación y nombres</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Elemento y E.O.</th><th>Fórmula</th><th>Nombre</th><th>Control</th></tr></thead><tbody><tr><td>Azufre +4</td><td>SO₂</td><td>óxido de azufre(IV) / dióxido de azufre</td><td><span class="u5Math" data-latex="%28%2B4%29%2B2%28-2%29%3D0" data-display="false"></span></td></tr><tr><td>Azufre +6</td><td>SO₃</td><td>óxido de azufre(VI) / trióxido de azufre</td><td><span class="u5Math" data-latex="%28%2B6%29%2B3%28-2%29%3D0" data-display="false"></span></td></tr><tr><td>Nitrógeno +3</td><td>N₂O₃</td><td>óxido de nitrógeno(III) / trióxido de dinitrógeno</td><td><span class="u5Math" data-latex="2%28%2B3%29%2B3%28-2%29%3D0" data-display="false"></span></td></tr><tr><td>Nitrógeno +5</td><td>N₂O₅</td><td>óxido de nitrógeno(V) / pentóxido de dinitrógeno</td><td><span class="u5Math" data-latex="2%28%2B5%29%2B5%28-2%29%3D0" data-display="false"></span></td></tr><tr><td>Cloro +1</td><td>Cl₂O</td><td>óxido de cloro(I) / monóxido de dicloro</td><td><span class="u5Math" data-latex="2%28%2B1%29%2B%28-2%29%3D0" data-display="false"></span></td></tr><tr><td>Cloro +7</td><td>Cl₂O₇</td><td>óxido de cloro(VII) / heptóxido de dicloro</td><td><span class="u5Math" data-latex="2%28%2B7%29%2B7%28-2%29%3D0" data-display="false"></span></td></tr><tr><td>Calcio +2</td><td>CaO</td><td>óxido de calcio</td><td><span class="u5Math" data-latex="%28%2B2%29%2B%28-2%29%3D0" data-display="false"></span></td></tr><tr><td>Sodio +1</td><td>Na₂O</td><td>óxido de sodio</td><td><span class="u5Math" data-latex="2%28%2B1%29%2B%28-2%29%3D0" data-display="false"></span></td></tr><tr><td>Hierro +2</td><td>FeO</td><td>óxido de hierro(II)</td><td><span class="u5Math" data-latex="%28%2B2%29%2B%28-2%29%3D0" data-display="false"></span></td></tr><tr><td>Hierro +3</td><td>Fe₂O₃</td><td>óxido de hierro(III)</td><td><span class="u5Math" data-latex="2%28%2B3%29%2B3%28-2%29%3D0" data-display="false"></span></td></tr></tbody></table></div><aside class="u5Tip"><strong>Clave:</strong> Para Cl₂O, el nombre por prefijos es monóxido de dicloro; «óxido de dicloro» omite la cantidad de oxígeno.</aside></div></details><details class="u5Subsolution"><summary>b) ¿Iónico o covalente?</summary><div><p><strong>Predominantemente iónicos:</strong> CaO, Na₂O, FeO y Fe₂O₃ (metal + oxígeno).</p><p><strong>Predominantemente covalentes:</strong> SO₂, SO₃, N₂O₃, N₂O₅, Cl₂O y Cl₂O₇ (no metales + oxígeno).</p></div></details><details class="u5Subsolution"><summary>c) Lewis: las diez especies</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Especie</th><th>Esqueleto o iones</th><th>Qué completar</th></tr></thead><tbody><tr><td>CaO</td><td>Ca²⁺ + [O]²⁻</td><td>O²⁻: cuatro pares libres.</td></tr><tr><td>Na₂O</td><td>2 Na⁺ + [O]²⁻</td><td>O²⁻: cuatro pares libres.</td></tr><tr><td>FeO</td><td>Fe²⁺ + [O]²⁻</td><td>O²⁻: cuatro pares libres.</td></tr><tr><td>Fe₂O₃</td><td>2 Fe³⁺ + 3 [O]²⁻</td><td>Cada O²⁻: cuatro pares libres.</td></tr><tr><td>SO₂</td><td>O=S=O</td><td>S: un par libre; cada O: dos. Resonancia equivalente.</td></tr><tr><td>SO₃</td><td>O=S(=O)=O</td><td>S central; cada O: dos pares libres.</td></tr><tr><td>N₂O₃</td><td>O=N–O–N=O</td><td>Cada N: un par libre; cada O terminal: dos; O puente: dos.</td></tr><tr><td>N₂O₅</td><td>O=N⁺(–O⁻)–O–N⁺(=O)–O⁻</td><td>O puente: dos pares libres; O terminal =: dos; O⁻: tres. En cada NO₂ intercambiá =O y O⁻ por resonancia.</td></tr><tr><td>Cl₂O</td><td>Cl–O–Cl</td><td>O: dos pares; cada Cl: tres pares.</td></tr><tr><td>Cl₂O₇</td><td>(O=)₃Cl–O–Cl(=O)₃</td><td>O puente: dos pares libres; cada O terminal: dos. Cada Cl se une a cuatro O.</td></tr></tbody></table></div><aside class="u5Tip"><strong>Clave:</strong> En N₂O₅ y Cl₂O₇ respetá la pista estructural de la consigna. Los dibujos con enlaces dativos o con enlaces múltiples son convenciones de Lewis: comprobá electrones y cargas formales.</aside></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',5,'serie-5',$cbc$Ejercicio 5.3$cbc$,$cbc$<div class="u5Verbatim" data-source="serie5_ejercicios_resueltos.md"><p><strong>5.3] La mayoría de los elementos de la Tabla Periódica forman compuestos binarios con hidrógeno y en ellos el hidrógeno tiene estado de oxidación -1 o +1.</strong></p><p><strong>a)</strong> Aplicando las reglas del estado de oxidación, escribir la fórmula y nombrar los compuestos binarios que forman con hidrógeno los elementos siguientes: 1) potasio; 2) calcio; 3) nitrógeno; 4) selenio; 5) silicio; 6) cloro; 7) oxígeno; 8) flúor.</p><p><strong>b)</strong> Hacer una lista de los compuestos predominantemente iónicos y otra de los compuestos predominantemente covalentes.</p><p><strong>c)</strong> Representar una estructura de Lewis para cada uno de ellos.</p></div>$cbc$,'Serie 5 · Química CBC · Cátedra Di Risio', 40, false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html, source_label=excluded.source_label, sort_order=excluded.sort_order, updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u5Lead">La primera decisión es si el H se une a un metal (H = −1) o a un no metal (H = +1).</p><details class="u5Subsolution" open><summary>a) Fórmula y nombre</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Elemento</th><th>Fórmula</th><th>Nombre</th></tr></thead><tbody><tr><td>K</td><td>KH</td><td>hidruro de potasio</td></tr><tr><td>Ca</td><td>CaH₂</td><td>hidruro de calcio</td></tr><tr><td>N</td><td>NH₃</td><td>amoníaco / trihidruro de nitrógeno</td></tr><tr><td>Se</td><td>H₂Se</td><td>seleniuro de hidrógeno</td></tr><tr><td>Si</td><td>SiH₄</td><td>silano / tetrahidruro de silicio</td></tr><tr><td>Cl</td><td>HCl</td><td>cloruro de hidrógeno</td></tr><tr><td>O</td><td>H₂O</td><td>agua</td></tr><tr><td>F</td><td>HF</td><td>fluoruro de hidrógeno</td></tr></tbody></table></div></div></details><details class="u5Subsolution"><summary>b) Tipo de unión</summary><div><p><strong>Iónicos:</strong> KH y CaH₂, en el modelo de hidruros salinos.</p><p><strong>Covalentes:</strong> NH₃, H₂Se, SiH₄, HCl, H₂O y HF.</p></div></details><details class="u5Subsolution"><summary>c) Lewis de cada compuesto</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Fórmula</th><th>Representación y pares libres</th><th>Unión</th></tr></thead><tbody><tr><td>KH</td><td>K⁺ + [H]⁻</td><td>iónico</td></tr><tr><td>CaH₂</td><td>Ca²⁺ + 2 [H]⁻</td><td>iónico</td></tr><tr><td>NH₃</td><td>N con 3 enlaces N–H y 1 par libre</td><td>covalente</td></tr><tr><td>H₂Se</td><td>H–Se–H; Se con 2 pares libres</td><td>covalente</td></tr><tr><td>SiH₄</td><td>Si con 4 enlaces Si–H</td><td>covalente</td></tr><tr><td>HCl</td><td>H–Cl; Cl con 3 pares libres</td><td>covalente</td></tr><tr><td>H₂O</td><td>H–O–H; O con 2 pares libres</td><td>covalente</td></tr><tr><td>HF</td><td>H–F; F con 3 pares libres</td><td>covalente</td></tr></tbody></table></div><aside class="u5Tip"><strong>Clave:</strong> En [H]⁻ hay dos electrones (dueto). En HCl, HF, H₂O y NH₃ se comparten pares; no dibujes iones libres como estructura de la molécula.</aside></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',5,'serie-5',$cbc$Ejercicio 5.4$cbc$,$cbc$<div class="u5Verbatim" data-source="serie5_ejercicios_resueltos.md"><p><strong>5.4] Dados los haluros de hidrógeno: <span class="u5Math" data-latex="%5Ctext%7BHF%7D%2C%20%5Ctext%7BHCl%7D%2C%20%5Ctext%7BHBr%7D" data-display="false"></span> y <span class="u5Math" data-latex="%5Ctext%7BHI%7D" data-display="false"></span>,</strong></p><p><strong>a)</strong> indicar cuál de los átomos presenta densidad de carga positiva y cuál negativa teniendo en cuenta la electronegatividad de los mismos;</p><p><strong>b)</strong> representar en cada caso el vector del dipolo de enlace;</p><p><strong>c)</strong> ordenar las moléculas en orden de polaridad creciente de su enlace;</p><p><strong>d)</strong> ¿Cuál de los haluros de hidrógeno tiene mayor carácter iónico?</p></div>$cbc$,'Serie 5 · Química CBC · Cátedra Di Risio', 50, false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html, source_label=excluded.source_label, sort_order=excluded.sort_order, updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u5Lead">Compará la electronegatividad del H con la de cada halógeno; después mirá el sentido del dipolo.</p><details class="u5Subsolution" open><summary>a) Cargas parciales</summary><div><p>En los cuatro enlaces, el halógeno atrae más el par: H lleva δ+ y F, Cl, Br o I lleva δ−.</p></div></details><details class="u5Subsolution"><summary>b) Vectores de enlace</summary><div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BH%7D%5E%7B%5Cdelta%2B%7D%5Clongrightarrow%5Cmathrm%7BF%7D%5E%7B%5Cdelta-%7D" data-display="true"></div></div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BH%7D%5E%7B%5Cdelta%2B%7D%5Clongrightarrow%5Cmathrm%7BCl%7D%5E%7B%5Cdelta-%7D" data-display="true"></div></div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BH%7D%5E%7B%5Cdelta%2B%7D%5Clongrightarrow%5Cmathrm%7BBr%7D%5E%7B%5Cdelta-%7D" data-display="true"></div></div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BH%7D%5E%7B%5Cdelta%2B%7D%5Clongrightarrow%5Cmathrm%7BI%7D%5E%7B%5Cdelta-%7D" data-display="true"></div></div><p>La flecha química apunta hacia el halógeno; la cruz, si se dibuja, queda del lado positivo (H).</p></div></details><details class="u5Subsolution"><summary>c) Polaridad creciente</summary><div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BHI%7D%3C%5Cmathrm%7BHBr%7D%3C%5Cmathrm%7BHCl%7D%3C%5Cmathrm%7BHF%7D" data-display="true"></div></div><p>Al subir en el grupo aumenta la electronegatividad del halógeno y la diferencia con H.</p></div></details><details class="u5Subsolution"><summary>d) Mayor carácter iónico</summary><div><p><strong>HF</strong>, por la mayor diferencia de electronegatividad. Sigue siendo una molécula con enlace covalente muy polar; «mayor carácter iónico» es una comparación, no una afirmación de que HF puro sea una red iónica.</p></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',5,'serie-5',$cbc$Ejercicio 5.5$cbc$,$cbc$<div class="u5Verbatim" data-source="serie5_ejercicios_resueltos.md"><p><strong>5.5] a)</strong> Según corresponda, escribir la fórmula química o nombrar a las sales binarias siguientes: 1) <span class="u5Math" data-latex="%5Ctext%7BFeCl%7D_3" data-display="false"></span>; 2) cloruro de hierro(II); 3) fluoruro de calcio; 4) <span class="u5Math" data-latex="%5Ctext%7BCoCl%7D_2" data-display="false"></span>; 5) sulfuro de hierro(II); 6) <span class="u5Math" data-latex="%5Ctext%7BZnS%7D" data-display="false"></span>; 7) <span class="u5Math" data-latex="%5Ctext%7BKCl%7D" data-display="false"></span>; 8) cloruro de aluminio.</p><p><strong>b)</strong> Indicar si se trata de compuestos predominantemente iónicos o covalentes.</p><p><strong>c)</strong> Representar una estructura de Lewis para cada una de ellas.</p></div>$cbc$,'Serie 5 · Química CBC · Cátedra Di Risio', 60, false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html, source_label=excluded.source_label, sort_order=excluded.sort_order, updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u5Lead">Separá mentalmente catión metálico y anión no metálico. El total de cargas positivas y negativas debe dar cero.</p><details class="u5Subsolution" open><summary>a) Fórmula o nombre</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>N.º</th><th>Fórmula</th><th>Nombre</th></tr></thead><tbody><tr><td>1</td><td>FeCl₃</td><td>cloruro de hierro(III)</td></tr><tr><td>2</td><td>FeCl₂</td><td>cloruro de hierro(II)</td></tr><tr><td>3</td><td>CaF₂</td><td>fluoruro de calcio</td></tr><tr><td>4</td><td>CoCl₂</td><td>cloruro de cobalto(II)</td></tr><tr><td>5</td><td>FeS</td><td>sulfuro de hierro(II)</td></tr><tr><td>6</td><td>ZnS</td><td>sulfuro de cinc</td></tr><tr><td>7</td><td>KCl</td><td>cloruro de potasio</td></tr><tr><td>8</td><td>AlCl₃</td><td>cloruro de aluminio</td></tr></tbody></table></div></div></details><details class="u5Subsolution"><summary>b) Unión predominante</summary><div><p>En el criterio de clasificación de la guía, las ocho son <strong>sales predominantemente iónicas</strong> (metal + no metal). Algunos compuestos, como AlCl₃, pueden tener carácter covalente importante según el estado físico; el modelo pedido aquí usa iones para formular.</p></div></details><details class="u5Subsolution"><summary>c) Lewis, una por una</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Fórmula</th><th>Iones que se representan</th></tr></thead><tbody><tr><td>FeCl₃</td><td>Fe³⁺ + 3 [Cl]⁻</td></tr><tr><td>FeCl₂</td><td>Fe²⁺ + 2 [Cl]⁻</td></tr><tr><td>CaF₂</td><td>Ca²⁺ + 2 [F]⁻</td></tr><tr><td>CoCl₂</td><td>Co²⁺ + 2 [Cl]⁻</td></tr><tr><td>FeS</td><td>Fe²⁺ + [S]²⁻</td></tr><tr><td>ZnS</td><td>Zn²⁺ + [S]²⁻</td></tr><tr><td>KCl</td><td>K⁺ + [Cl]⁻</td></tr><tr><td>AlCl₃</td><td>Al³⁺ + 3 [Cl]⁻</td></tr></tbody></table></div><aside class="u5Tip"><strong>Clave:</strong> Cada haluro [Cl]⁻ o [F]⁻ lleva cuatro pares libres; [S]²⁻ también. Las cantidades delante de cada ion no son enlaces entre ellos.</aside></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',5,'serie-5',$cbc$Ejercicio 5.6$cbc$,$cbc$<div class="u5Verbatim" data-source="serie5_ejercicios_resueltos.md"><p><strong>5.6] a)</strong> Escribir la fórmula química o nombrar a los hidróxidos siguientes: 1) hidróxido de sodio; 2) <span class="u5Math" data-latex="%5Ctext%7BCa%28OH%29%7D_2" data-display="false"></span>; 3) hidróxido de aluminio; 4) <span class="u5Math" data-latex="%5Ctext%7BFe%28OH%29%7D_3" data-display="false"></span>; 5) <span class="u5Math" data-latex="%5Ctext%7BCu%28OH%29%7D_2" data-display="false"></span>; 6) hidróxido de manganeso(II).</p><p><strong>b)</strong> ¿Son compuestos predominantemente iónicos o covalentes?</p><p><strong>c)</strong> Representar una estructura de Lewis para cada uno de ellos.</p></div>$cbc$,'Serie 5 · Química CBC · Cátedra Di Risio', 70, false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html, source_label=excluded.source_label, sort_order=excluded.sort_order, updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u5Lead">El grupo OH⁻ permanece unido y vale −1. Si se necesita más de uno, se escribe entre paréntesis.</p><details class="u5Subsolution" open><summary>a) Fórmula y nombre</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>N.º</th><th>Fórmula</th><th>Nombre</th><th>Iones</th></tr></thead><tbody><tr><td>1</td><td>NaOH</td><td>hidróxido de sodio</td><td>Na⁺ + [OH]⁻</td></tr><tr><td>2</td><td>Ca(OH)₂</td><td>hidróxido de calcio</td><td>Ca²⁺ + 2 [OH]⁻</td></tr><tr><td>3</td><td>Al(OH)₃</td><td>hidróxido de aluminio</td><td>Al³⁺ + 3 [OH]⁻</td></tr><tr><td>4</td><td>Fe(OH)₃</td><td>hidróxido de hierro(III)</td><td>Fe³⁺ + 3 [OH]⁻</td></tr><tr><td>5</td><td>Cu(OH)₂</td><td>hidróxido de cobre(II)</td><td>Cu²⁺ + 2 [OH]⁻</td></tr><tr><td>6</td><td>Mn(OH)₂</td><td>hidróxido de manganeso(II)</td><td>Mn²⁺ + 2 [OH]⁻</td></tr></tbody></table></div></div></details><details class="u5Subsolution"><summary>b) ¿Iónico o covalente?</summary><div><p>Predomina la atracción <strong>iónica entre el catión metálico y OH⁻</strong>. Dentro de cada OH⁻, O y H están unidos mediante un enlace covalente polar.</p></div></details><details class="u5Subsolution"><summary>c) Lewis para los seis</summary><div><p>Usá la columna de iones de la tabla: en cada [OH]⁻ dibujá O–H, tres pares libres sobre O y la carga −1 fuera del corchete. Repetí el ion 1, 2 o 3 veces según el subíndice; el metal queda separado con su carga.</p><aside class="u5Tip"><strong>Clave:</strong> Ejemplo: Ca(OH)₂ = Ca²⁺ + 2 [OH]⁻. El «2» multiplica a todo el grupo OH.</aside></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',5,'serie-5',$cbc$Ejercicio 5.7$cbc$,$cbc$<div class="u5Verbatim" data-source="serie5_ejercicios_resueltos.md"><p><strong>5.7] a)</strong> Escribir la fórmula química y nombrar a los oxoácidos de: 1) azufre, con estados de oxidación +4 y +6; 2) nitrógeno, con estados de oxidación +3 y +5; 3) cloro, con estados de oxidación +1 y +5; 4) silicio, con estado de oxidación +4.</p><p><strong>b)</strong> ¿Son compuestos predominantemente iónicos o covalentes?</p><p><strong>c)</strong> Representar una estructura de Lewis para cada uno de ellos.</p></div>$cbc$,'Serie 5 · Química CBC · Cátedra Di Risio', 80, false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html, source_label=excluded.source_label, sort_order=excluded.sort_order, updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u5Lead">El H va unido al O. Para formular, podés partir del óxido correspondiente y sumar agua, cuidando los coeficientes.</p><details class="u5Subsolution" open><summary>a) Fórmulas, nombres y formación</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Centro y E.O.</th><th>Oxoácido</th><th>Nombre</th></tr></thead><tbody><tr><td>S +4</td><td>H₂SO₃</td><td>ácido sulfuroso</td></tr><tr><td>S +6</td><td>H₂SO₄</td><td>ácido sulfúrico</td></tr><tr><td>N +3</td><td>HNO₂</td><td>ácido nitroso</td></tr><tr><td>N +5</td><td>HNO₃</td><td>ácido nítrico</td></tr><tr><td>Cl +1</td><td>HClO</td><td>ácido hipocloroso</td></tr><tr><td>Cl +5</td><td>HClO₃</td><td>ácido clórico</td></tr><tr><td>Si +4</td><td>H₂SiO₃</td><td>ácido silícico (fórmula formal de la guía)</td></tr></tbody></table></div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BSO_2%2BH_2O%5Crightarrow%20H_2SO_3%7D" data-display="true"></div></div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BSO_3%2BH_2O%5Crightarrow%20H_2SO_4%7D" data-display="true"></div></div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BN_2O_3%2BH_2O%5Crightarrow%202HNO_2%7D" data-display="true"></div></div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BN_2O_5%2BH_2O%5Crightarrow%202HNO_3%7D" data-display="true"></div></div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BCl_2O%2BH_2O%5Crightarrow%202HClO%7D" data-display="true"></div></div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BCl_2O_5%2BH_2O%5Crightarrow%202HClO_3%7D" data-display="true"></div></div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BSiO_2%2BH_2O%5Crightarrow%20H_2SiO_3%7D" data-display="true"></div></div><aside class="u5Tip"><strong>Clave:</strong> Para N y Cl hay dos moléculas de ácido por cada óxido dimerizado. La ecuación de SiO₂ + agua es una formulación formal de la guía; los ácidos silícicos reales pueden formar estructuras condensadas.</aside></div></details><details class="u5Subsolution"><summary>b) Tipo de unión</summary><div><p>Son <strong>predominantemente covalentes</strong>; dentro de la molécula hay enlaces O–H y centro–O. En agua, un ácido puede ionizarse.</p></div></details><details class="u5Subsolution"><summary>c) Lewis de todos los oxoácidos</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Fórmula</th><th>Esqueleto de Lewis orientativo</th></tr></thead><tbody><tr><td>H₂SO₃</td><td>HO–S(=O)–OH; S con 1 par libre</td></tr><tr><td>H₂SO₄</td><td>HO–S(=O)₂–OH</td></tr><tr><td>HNO₂</td><td>HO–N=O; N con 1 par libre</td></tr><tr><td>HNO₃</td><td>HO–N⁺(=O)–O⁻; dos contribuyentes</td></tr><tr><td>HClO</td><td>H–O–Cl; Cl con 3 pares libres</td></tr><tr><td>HClO₃</td><td>HO–Cl(=O)₂</td></tr><tr><td>H₂SiO₃</td><td>HO–Si(=O)–OH (representación formal)</td></tr></tbody></table></div><aside class="u5Tip"><strong>Clave:</strong> En HNO₃, N respeta octeto: una forma tiene N⁺ y un O⁻; las dos posiciones no protonadas intercambian el doble enlace por resonancia.</aside></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',5,'serie-5',$cbc$Ejercicio 5.8$cbc$,$cbc$<div class="u5Verbatim" data-source="serie5_ejercicios_resueltos.md"><p><strong>5.8] a)</strong> Nombrar a cada una de las oxosales e hidrogenoxosales siguientes:</p><p><strong>1)</strong> <span class="u5Math" data-latex="%5Ctext%7BCaSiO%7D_3%2C%20%5Ctext%7BNaClO%7D%2C%20%5Ctext%7BNa%7D_2%5Ctext%7BSO%7D_3" data-display="false"></span> y <span class="u5Math" data-latex="%5Ctext%7BKHSO%7D_3" data-display="false"></span>;</p><p><strong>2)</strong> <span class="u5Math" data-latex="%5Ctext%7BCaCO%7D_3%2C%20%5Ctext%7BKHCO%7D_3%2C%20%5Ctext%7BNaNO%7D_3" data-display="false"></span> y <span class="u5Math" data-latex="%5Ctext%7BK%7D_3%5Ctext%7BPO%7D_4" data-display="false"></span>.</p><p><strong>b)</strong> Escribir la fórmula química y nombrar al oxoanión o hidrogenooxoanión involucrado en cada una de ellas.</p><p><strong>c)</strong> Representar la estructura de Lewis del <span class="u5Math" data-latex="%5Ctext%7BNaClO%7D" data-display="false"></span> y del <span class="u5Math" data-latex="%5Ctext%7BKHCO%7D_3" data-display="false"></span>.</p></div>$cbc$,'Serie 5 · Química CBC · Cátedra Di Risio', 90, false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html, source_label=excluded.source_label, sort_order=excluded.sort_order, updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u5Lead">Ubicá el catión a la izquierda y conservá el oxoanión como bloque. Si el anión aún tiene H, el nombre comienza con «hidrógeno».</p><details class="u5Subsolution" open><summary>a) Nombre de las ocho sales</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Grupo</th><th>Fórmula</th><th>Nombre</th></tr></thead><tbody><tr><td>1</td><td>CaSiO₃</td><td>silicato de calcio</td></tr><tr><td>1</td><td>NaClO</td><td>hipoclorito de sodio</td></tr><tr><td>1</td><td>Na₂SO₃</td><td>sulfito de sodio</td></tr><tr><td>1</td><td>KHSO₃</td><td>hidrogenosulfito de potasio</td></tr><tr><td>2</td><td>CaCO₃</td><td>carbonato de calcio</td></tr><tr><td>2</td><td>KHCO₃</td><td>hidrogenocarbonato de potasio</td></tr><tr><td>2</td><td>NaNO₃</td><td>nitrato de sodio</td></tr><tr><td>2</td><td>K₃PO₄</td><td>fosfato de potasio (ortofosfato)</td></tr></tbody></table></div></div></details><details class="u5Subsolution"><summary>b) Anión correspondiente</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Sal</th><th>Anión y nombre</th></tr></thead><tbody><tr><td>CaSiO₃</td><td>SiO₃²⁻ · silicato</td></tr><tr><td>NaClO</td><td>ClO⁻ · hipoclorito</td></tr><tr><td>Na₂SO₃</td><td>SO₃²⁻ · sulfito</td></tr><tr><td>KHSO₃</td><td>HSO₃⁻ · hidrogenosulfito</td></tr><tr><td>CaCO₃</td><td>CO₃²⁻ · carbonato</td></tr><tr><td>KHCO₃</td><td>HCO₃⁻ · hidrogenocarbonato</td></tr><tr><td>NaNO₃</td><td>NO₃⁻ · nitrato</td></tr><tr><td>K₃PO₄</td><td>PO₄³⁻ · fosfato</td></tr></tbody></table></div><aside class="u5Tip"><strong>Clave:</strong> La carga se obtiene restando las cargas positivas: Ca²⁺ necesita SiO₃²⁻; K⁺ necesita HCO₃⁻.</aside></div></details><details class="u5Subsolution"><summary>c) Lewis pedido</summary><div><div class="u5Step"><span>NaClO</span><div><p>Separá Na⁺ y [Cl–O]⁻. La carga formal −1 queda en O; en el anión, Cl y O tienen tres pares libres cada uno.</p></div></div><div class="u5Step"><span>KHCO₃</span><div><p>Separá K⁺ y [HO–C(=O)–O]⁻. El H se une a O. Entre los dos O no protonados hay resonancia: alternan el doble enlace y la carga −1.</p></div></div></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',5,'serie-5',$cbc$Ejercicio 5.9$cbc$,$cbc$<div class="u5Verbatim" data-source="serie5_ejercicios_resueltos.md"><p><strong>5.9] En la Tabla Periódica al final de esta guía se informan los estados de oxidación más comunes de los elementos. Escribir al menos una fórmula de compuestos del nitrógeno con oxígeno y con hidrógeno teniendo en cuenta los estados de oxidación del nitrógeno informados en dicha tabla.</strong></p></div>$cbc$,'Serie 5 · Química CBC · Cátedra Di Risio', 100, false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html, source_label=excluded.source_label, sort_order=excluded.sort_order, updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u5Lead">La consigna pide al menos una fórmula con O y una con H. NH₃ y NO ya alcanzan; la tabla muestra más posibilidades y comprueba el E.O. de N.</p><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>Con qué se combina</th><th>Fórmula</th><th>E.O. de N</th><th>Comprobación</th></tr></thead><tbody><tr><td>Con H</td><td>NH₃</td><td>N = −3</td><td><span class="u5Math" data-latex="x%2B3%28%2B1%29%3D0%5CRightarrow%20x%3D-3" data-display="false"></span></td></tr><tr><td>Con O</td><td>N₂O</td><td>N = +1</td><td><span class="u5Math" data-latex="2x%2B%28-2%29%3D0%5CRightarrow%20x%3D%2B1" data-display="false"></span></td></tr><tr><td>Con O</td><td>NO</td><td>N = +2</td><td><span class="u5Math" data-latex="x%2B%28-2%29%3D0%5CRightarrow%20x%3D%2B2" data-display="false"></span></td></tr><tr><td>Con O</td><td>N₂O₃</td><td>N = +3</td><td><span class="u5Math" data-latex="2x%2B3%28-2%29%3D0%5CRightarrow%20x%3D%2B3" data-display="false"></span></td></tr><tr><td>Con O</td><td>NO₂</td><td>N = +4</td><td><span class="u5Math" data-latex="x%2B2%28-2%29%3D0%5CRightarrow%20x%3D%2B4" data-display="false"></span></td></tr><tr><td>Con O</td><td>N₂O₅</td><td>N = +5</td><td><span class="u5Math" data-latex="2x%2B5%28-2%29%3D0%5CRightarrow%20x%3D%2B5" data-display="false"></span></td></tr></tbody></table></div><aside class="u5Tip"><strong>Clave:</strong> En NH₃, H = +1 y N = −3. En un óxido, O = −2 y N debe compensarlo con E.O. positivo.</aside>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',5,'serie-5',$cbc$Ejercicio 5.10$cbc$,$cbc$<div class="u5Verbatim" data-source="serie5_ejercicios_resueltos.md"><p><strong>5.10] a)</strong> Según corresponda, escribir la fórmula química o nombrar a los compuestos siguientes: 1) sulfato de calcio; 2) hidrogenocarbonato de sodio; 3) <span class="u5Math" data-latex="%5Ctext%7BNaHSO%7D_3" data-display="false"></span>; 4) sulfato de amonio; 5) hidrogenosulfuro de sodio; 6) <span class="u5Math" data-latex="%5Ctext%7BBa%28OH%29%7D_2" data-display="false"></span>; 7) <span class="u5Math" data-latex="%5Ctext%7BNa%7D_2%5Ctext%7BCO%7D_3" data-display="false"></span>; 8) <span class="u5Math" data-latex="%5Ctext%7BCaHPO%7D_4" data-display="false"></span>; 9) hidróxido de cinc; 10) <span class="u5Math" data-latex="%5Ctext%7BFe%28OH%29%7D_2" data-display="false"></span>; 11) ácido fosfórico.</p><p><strong>b)</strong> Indicar a qué tipo de compuesto de los estudiados en las secciones siguientes corresponde cada uno.</p><p><strong>c)</strong> Representar una estructura de Lewis para cada uno de ellos.</p></div>$cbc$,'Serie 5 · Química CBC · Cátedra Di Risio', 110, false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html, source_label=excluded.source_label, sort_order=excluded.sort_order, updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u5Lead">Identificá primero los grupos OH⁻, NH₄⁺ y los oxoaniones. Una misma fórmula puede contener varios iones sin dejar de tener una sola unidad fórmula.</p><details class="u5Subsolution" open><summary>a) Fórmula o nombre</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>N.º</th><th>Dato dado</th><th>Respuesta</th></tr></thead><tbody><tr><td>1</td><td>sulfato de calcio</td><td>CaSO₄</td></tr><tr><td>2</td><td>hidrogenocarbonato de sodio</td><td>NaHCO₃</td></tr><tr><td>3</td><td>NaHSO₃</td><td>hidrogenosulfito de sodio</td></tr><tr><td>4</td><td>sulfato de amonio</td><td>(NH₄)₂SO₄</td></tr><tr><td>5</td><td>hidrogenosulfuro de sodio</td><td>NaHS</td></tr><tr><td>6</td><td>Ba(OH)₂</td><td>hidróxido de bario</td></tr><tr><td>7</td><td>Na₂CO₃</td><td>carbonato de sodio</td></tr><tr><td>8</td><td>CaHPO₄</td><td>hidrogenofosfato de calcio</td></tr><tr><td>9</td><td>hidróxido de cinc</td><td>Zn(OH)₂</td></tr><tr><td>10</td><td>Fe(OH)₂</td><td>hidróxido de hierro(II)</td></tr><tr><td>11</td><td>ácido fosfórico</td><td>H₃PO₄</td></tr></tbody></table></div></div></details><details class="u5Subsolution"><summary>b) Familia y cantidad de elementos</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>N.º</th><th>Fórmula o nombre</th><th>Familia · elementos</th></tr></thead><tbody><tr><td>1</td><td>CaSO₄</td><td>oxosal · ternario</td></tr><tr><td>2</td><td>NaHCO₃</td><td>hidrogenoxosal · cuaternario</td></tr><tr><td>3</td><td>NaHSO₃</td><td>hidrogenoxosal · cuaternario</td></tr><tr><td>4</td><td>(NH₄)₂SO₄</td><td>oxosal de amonio · cuaternario</td></tr><tr><td>5</td><td>NaHS</td><td>hidrogenosal · ternario</td></tr><tr><td>6</td><td>Ba(OH)₂</td><td>hidróxido · ternario</td></tr><tr><td>7</td><td>Na₂CO₃</td><td>oxosal · ternario</td></tr><tr><td>8</td><td>CaHPO₄</td><td>hidrogenoxosal · cuaternario</td></tr><tr><td>9</td><td>Zn(OH)₂</td><td>hidróxido · ternario</td></tr><tr><td>10</td><td>Fe(OH)₂</td><td>hidróxido · ternario</td></tr><tr><td>11</td><td>H₃PO₄</td><td>oxoácido · ternario</td></tr></tbody></table></div><aside class="u5Tip"><strong>Clave:</strong> Corrección del borrador: (NH₄)₂SO₄ contiene N, H, S y O: <strong>cuatro elementos distintos</strong>. Es cuaternario, aunque sea una oxosal de amonio.</aside></div></details><details class="u5Subsolution"><summary>c) Lewis de cada una</summary><div><div class="u5TableScroll"><table class="u5Table"><thead><tr><th>N.º</th><th>Partículas o esqueleto a dibujar</th></tr></thead><tbody><tr><td>1</td><td>Ca²⁺ + SO₄²⁻</td></tr><tr><td>2</td><td>Na⁺ + HCO₃⁻</td></tr><tr><td>3</td><td>Na⁺ + HSO₃⁻</td></tr><tr><td>4</td><td>2 NH₄⁺ + SO₄²⁻</td></tr><tr><td>5</td><td>Na⁺ + HS⁻</td></tr><tr><td>6</td><td>Ba²⁺ + 2 OH⁻</td></tr><tr><td>7</td><td>2 Na⁺ + CO₃²⁻</td></tr><tr><td>8</td><td>Ca²⁺ + HPO₄²⁻</td></tr><tr><td>9</td><td>Zn²⁺ + 2 OH⁻</td></tr><tr><td>10</td><td>Fe²⁺ + 2 OH⁻</td></tr><tr><td>11</td><td>HO–P(=O)(OH)₂</td></tr></tbody></table></div><p>Para SO₄²⁻, CO₃²⁻, HCO₃⁻, HSO₃⁻ y HPO₄²⁻, dibujá enlaces covalentes internos, pares libres y carga del anión. En las sales, separá ese anión del catión. En OH⁻, dibujá O–H y tres pares libres sobre O. En NH₄⁺, cuatro N–H; H₃PO₄ es una molécula covalente con P central y tres grupos O–H.</p><aside class="u5Tip"><strong>Clave:</strong> El cuadro resume la cantidad de iones, pero no reemplaza los pares de electrones: completalos al pasar cada esqueleto a Lewis.</aside></div></details>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
with item as (insert into public.exercises(subject,unit_no,section_key,title,statement_html,source_label,sort_order,is_public) values ('chemistry',5,'serie-5',$cbc$Ejercicio 5.11$cbc$,$cbc$<div class="u5Verbatim" data-source="serie5_ejercicios_resueltos.md"><p><strong>5.11] Dados los siguientes compuestos: <span class="u5Math" data-latex="%5Ctext%7BCO%7D_2%2C%20%5Ctext%7BBaCO%7D_3%2C%20%5Ctext%7BCO%7D%2C%20%5Ctext%7BH%7D_2%5Ctext%7BCO%7D_3%2C%20%5Ctext%7BFe%7D_2%28%5Ctext%7BCO%7D_3%29_3%2C%20%5Ctext%7BFeCO%7D_3" data-display="false"></span>; nombrar al compuesto iónico que contiene hierro en estado de oxidación +3.</strong></p><p><em>Problema de examen de la Cátedra - 2025.</em></p></div>$cbc$,'Serie 5 · Química CBC · Cátedra Di Risio', 120, false) on conflict (subject,unit_no,section_key,title) do update set statement_html=excluded.statement_html, source_label=excluded.source_label, sort_order=excluded.sort_order, updated_at=now() returning id) insert into public.exercise_solutions(exercise_id,solution_html,final_answer,student_visible) select id,$cbc$<p class="u5Lead">Entre las opciones, primero descartá las que no tienen Fe. Después usá la carga del carbonato.</p><div class="u5Step"><span>1 · Anión</span><div><div class="u5Equation"><div class="u5Math" data-latex="%5Cmathrm%7BCO_3%5E%7B2-%7D%7D%5Cquad%5Ctext%7Btiene%20carga%20%7D-2" data-display="true"></div></div></div></div><div class="u5Step"><span>2 · FeCO₃</span><div><div class="u5Equation"><div class="u5Math" data-latex="x%2B%28-2%29%3D0%5CRightarrow%20x%3D%2B2" data-display="true"></div></div><p>Aquí es carbonato de hierro(II), así que no cumple la condición.</p></div></div><div class="u5Step"><span>3 · Fe₂(CO₃)₃</span><div><div class="u5Equation"><div class="u5Math" data-latex="2x%2B3%28-2%29%3D0" data-display="true"></div></div><div class="u5Equation"><div class="u5Math" data-latex="2x-6%3D0%5CRightarrow%20x%3D%2B3" data-display="true"></div></div><p>Cada Fe tiene estado de oxidación +3.</p></div></div><aside class="u5Tip"><strong>Clave:</strong> <strong>Respuesta: Fe₂(CO₃)₃, carbonato de hierro(III).</strong></aside>$cbc$,null,true from item on conflict(exercise_id) do update set solution_html=excluded.solution_html,final_answer=excluded.final_answer,student_visible=excluded.student_visible,updated_at=now();
commit;
